package com.cognizant.stablecoins.payment.flow;
import com.cognizant.stablecoins.flow.FlowContract.*;
import com.cognizant.stablecoins.payment.routing.*;
import com.cognizant.stablecoins.payment.intent.*;
import com.cognizant.stablecoins.payment.support.IntentFixtures;
import org.junit.jupiter.api.*;
import org.springframework.mock.env.MockEnvironment;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import static org.assertj.core.api.Assertions.*;
class OwnerEvidenceAssemblerTest {
 final Instant now=Instant.now();final UUID id=UUID.randomUUID();
 final Request request=new Request(id,"PAY-1","CORR-1",IntentFixtures.CUSTOMER,new BigDecimal("10000"),new BigDecimal("10000"),"0x"+"1".repeat(40),"USDC_WALLET","AUTO","USD-USDC-WALLET",IntentFixtures.DEADLINE,Set.of("SIMULATED-PROVIDER-A"));
 Quote quote(BigDecimal fraud){return new Quote(id,UUID.randomUUID(),1,"SIMULATED-PROVIDER-A","simulation-v1",request.sourceUsd(),request.transferUsdc(),new BigDecimal("2.00"),990,1000,120000,fraud,true,now,now.plusSeconds(300));}
 Treasury treasury(BigDecimal usdc,BigDecimal eth,Instant expiry){return new Treasury("LIVE","base-sepolia",84532,"0x036CbD53842c5426634e7929541eC2318f3dCF7e","0x"+"2".repeat(40),usdc,BigDecimal.ZERO,usdc,eth,BigDecimal.ZERO,eth,new BigDecimal("65000"),new BigDecimal("78000"),new BigDecimal("1000000000"),new BigDecimal("0.00012345"),now,expiry,List.of());}
 final OwnerEvidenceAssembler assembler=new OwnerEvidenceAssembler(new MockEnvironment().withProperty("app.flow.simulation.eth-usd-budget","2000"));
 AssessmentResult assess(OwnerEvidenceAssembler.Prepared p){var intent=new PaymentIntentSnapshot(UUID.randomUUID(),1,request.customerId(),"creator",now,SettlementAsset.USDC,true,true,IntentFixtures.intent(BeneficiaryOutcome.USDC_WALLET),IntentFixtures.policy("v1"));return new DeterministicRoutingAssessmentService(new AssessmentRules("v1",Duration.ofMinutes(5),Duration.ofHours(24),100,95,new BigDecimal("0.95"),new BigDecimal("30"),new BigDecimal("100"),20,200),p.evidence().candidates().getFirst().network(),Clock.fixed(now,ZoneOffset.UTC)).assess(IntentFixtures.ACTOR,p.context(),intent,p.evidence());}
 @Test void allSevenOwnerSignalsPassExistingDeterministicAssessment(){var p=assembler.assemble(request,quote(BigDecimal.TEN),treasury(new BigDecimal("20000"),BigDecimal.ONE,now.plusSeconds(120)));assertThat(p.evidence().observations()).hasSize(7);assertThat(assess(p).status()).isEqualTo(AssessmentResult.Status.ASSESSED);assertThat(p.quote().totalFeeUsd()).isEqualByComparingTo("2.25");}
 @Test void preservesLiveLiquidityAndSimulatedQuoteProvenance(){var p=assembler.assemble(request,quote(BigDecimal.TEN),treasury(new BigDecimal("20000"),BigDecimal.ONE,now.plusSeconds(120)));for(var o:p.evidence().observations())assertThat(o.evidenceMode()).isEqualTo(o.signalType()==RoutingEvidence.SignalType.LIQUIDITY?RoutingEvidence.EvidenceMode.LIVE:RoutingEvidence.EvidenceMode.SIMULATED);assertThat(p.quote().simulated()).isTrue();}
 @Test void insufficientUsdcCannotBecomeEligible(){var p=assembler.assemble(request,quote(BigDecimal.TEN),treasury(BigDecimal.ONE,BigDecimal.ONE,now.plusSeconds(120)));assertThat(assess(p).status()).isEqualTo(AssessmentResult.Status.NO_ELIGIBLE_ROUTE);}
 @Test void insufficientEthCannotBecomeEligible(){var p=assembler.assemble(request,quote(BigDecimal.TEN),treasury(new BigDecimal("20000"),BigDecimal.ZERO,now.plusSeconds(120)));assertThat(assess(p).status()).isEqualTo(AssessmentResult.Status.NO_ELIGIBLE_ROUTE);}
 @Test void staleReadinessRequiresNewEvidence(){var p=assembler.assemble(request,quote(BigDecimal.TEN),treasury(new BigDecimal("20000"),BigDecimal.ONE,now.minusSeconds(1)));assertThat(assess(p).status()).isEqualTo(AssessmentResult.Status.INSUFFICIENT_EVIDENCE);}
 @Test void fraudThresholdStillExcludesRoute(){var p=assembler.assemble(request,quote(new BigDecimal("95")),treasury(new BigDecimal("20000"),BigDecimal.ONE,now.plusSeconds(120)));assertThat(assess(p).status()).isEqualTo(AssessmentResult.Status.NO_ELIGIBLE_ROUTE);}
 @Test void rejectsForeignQuoteBinding(){var q=quote(BigDecimal.TEN);q=new Quote(UUID.randomUUID(),q.quoteId(),1,q.providerId(),q.simulationVersion(),q.sourceUsd(),q.transferUsdc(),q.feeUsd(),q.completed(),q.attempts(),q.latencyMillis(),q.fraudScore(),true,q.createdAt(),q.expiresAt());var foreign=q;assertThatThrownBy(()->assembler.assemble(request,foreign,treasury(new BigDecimal("20000"),BigDecimal.ONE,now.plusSeconds(120)))).hasMessage("OWNER_QUOTE_BINDING_MISMATCH");}

 @Test void providerQuotesBecomeDistinctComparableCandidates(){var r=request;var two=new Request(r.requestId(),r.paymentId(),r.correlationId(),r.customerId(),r.sourceUsd(),r.transferUsdc(),r.recipientWallet(),r.outcome(),r.requestedRail(),r.corridor(),r.deadline(),Set.of("SIMULATED-PROVIDER-A","SIMULATED-PROVIDER-B"));var a=quote(BigDecimal.TEN);var b=new Quote(id,UUID.randomUUID(),1,"SIMULATED-PROVIDER-B",a.simulationVersion(),a.sourceUsd(),a.transferUsdc(),new BigDecimal("5.00"),990,1000,60000,BigDecimal.TEN,true,now,now.plusSeconds(300));var captured=assembler.assemble(two,List.of(a,b),treasury(new BigDecimal("20000"),BigDecimal.ONE,now.plusSeconds(120)));assertThat(captured.evidence().candidates()).hasSize(2);assertThat(captured.evidence().observations()).hasSize(14).extracting(RoutingEvidence.Observation::signalId).doesNotHaveDuplicates();var assessment=assess(new OwnerEvidenceAssembler.Prepared(captured.context(),captured.evidence(),captured.quotes().getFirst()));assertThat(assessment.status()).isEqualTo(AssessmentResult.Status.ASSESSED);assertThat(assessment.preferredCandidateId()).isEqualTo("STABLECOIN-SIMULATED-PROVIDER-B");}
 PreparedBank bank(java.math.BigDecimal available){var r=new Request(id,request.paymentId(),request.correlationId(),request.customerId(),request.sourceUsd(),request.transferUsdc(),request.recipientWallet(),"SIMULATED_BANK_INR","AUTO","USD-USDC-INR",IntentFixtures.DEADLINE,request.providerIds());var q=quote(BigDecimal.TEN);q=new Quote(q.requestId(),q.quoteId(),q.version(),q.providerId(),q.simulationVersion(),q.sourceUsd(),q.transferUsdc(),q.feeUsd(),q.completed(),q.attempts(),q.latencyMillis(),q.fraudScore(),q.available(),q.createdAt(),q.expiresAt(),"INR",new BigDecimal("830000"),new BigDecimal("83"),available);var p=assembler.assemble(r,q,treasury(new BigDecimal("20000"),BigDecimal.ONE,now.plusSeconds(120)));var intent=new PaymentIntentSnapshot(UUID.randomUUID(),1,r.customerId(),"creator",now,SettlementAsset.USDC,true,true,IntentFixtures.intent(BeneficiaryOutcome.SIMULATED_BANK_INR),IntentFixtures.policy("v1"));var result=new DeterministicRoutingAssessmentService(new AssessmentRules("v1",Duration.ofMinutes(5),Duration.ofHours(24),100,95,new BigDecimal("0.95"),new BigDecimal("30"),new BigDecimal("100"),20,200),p.evidence().candidates().getFirst().network(),Clock.fixed(now,ZoneOffset.UTC)).assess(IntentFixtures.ACTOR,p.context(),intent,p.evidence());return new PreparedBank(p,result);}
 record PreparedBank(OwnerEvidenceAssembler.Prepared prepared,AssessmentResult assessment){}
 @Test void bankQuoteComparesLikeForLikeUsingSimulatedFiatLiquidity(){var b=bank(new BigDecimal("1000000"));assertThat(b.assessment().status()).isEqualTo(AssessmentResult.Status.ASSESSED);assertThat(b.prepared().quote().payoutAmounts()).containsEntry(BeneficiaryOutcome.SIMULATED_BANK_INR,new BigDecimal("8.3E+5"));assertThat(b.prepared().evidence().observations().stream().filter(o->o.signalType()==RoutingEvidence.SignalType.LIQUIDITY).findFirst().orElseThrow().evidenceMode()).isEqualTo(RoutingEvidence.EvidenceMode.SIMULATED);}
 @Test void bankQuoteCannotIgnoreMissingProviderFiat(){assertThat(bank(BigDecimal.ZERO).assessment().status()).isEqualTo(AssessmentResult.Status.NO_ELIGIBLE_ROUTE);}
}
